// src/pages/InternalDashboard.tsx
import React, { useEffect, useState } from "react";
import api from "../api";
import io from "socket.io-client"; // see section 2 below

// The type describing ONE ticket
type Ticket = {
  _id: string;
  title: string;
  description?: string;
  status: "open" | "in_progress" | "closed";
  category: "billing" | "technical" | "general";
  priority: "low" | "medium" | "high";
  createdBy: any;
  assignee: any;
};

// ✅ 1) socket client
const socket = io("http://localhost:5050", { withCredentials: true });

// ✅ 2) props type
interface InternalDashboardProps {
  name: string;
}

// ✅ 3) use props type in React.FC
const InternalDashboard: React.FC<InternalDashboardProps> = ({ name }) => {
  const [tickets, setTickets] = useState<Ticket[]>([]);

  // Load tickets assigned to this internal user
  const fetchTickets = async () => {
    try {
      const res = await api.get<Ticket[]>("/tickets");
      setTickets(res.data);
    } catch (err) {
      console.error("Error fetching tickets:", err);
    }
  };

  useEffect(() => {
    fetchTickets();

    const handleUpdated = () => fetchTickets();
    const handleCreated = () => fetchTickets();

    socket.on("ticketUpdated", handleUpdated);
    socket.on("ticketCreated", handleCreated);

    return () => {
      socket.off("ticketUpdated", handleUpdated);
      socket.off("ticketCreated", handleCreated);
    };
  }, []);

  return (
    <div>
      <h1>Internal Dashboard</h1>
      <p>Welcome, {name}</p>

      <h2>Assigned Tickets</h2>
      <ul>
        {tickets.map((t) => (
          <li key={t._id}>
            <strong>{t.title}</strong> – {t.status}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default InternalDashboard;
